import { useState } from 'react';
import { countRender } from './renderCounter';

const ROWS = Array.from({ length: 2000 }, (_, i) => ({
  id: i,
  name: `Jugador ${i}`,
  score: (i * 37) % 500,
}));

function Row({ player, onSelect }) {
  countRender('Row');
  return (
    <tr onClick={() => onSelect(player.id)}>
      <td>{player.name}</td>
      <td>{player.score}</td>
    </tr>
  );
}

function Toolbar({ onReset }) {
  countRender('Toolbar');
  return <button onClick={onReset}>Reiniciar</button>;
}

export default function Dashboard() {
  countRender('Dashboard');
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState(null);

  // Se recalcula en CADA render, incluso al cambiar `selected`.
  const visible = ROWS.filter((row) =>
    row.name.toLowerCase().includes(query.toLowerCase()),
  );

  return (
    <div>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <Toolbar onReset={() => setQuery('')} />
      <p>Seleccionado: {selected ?? '—'}</p>
      <table>
        <tbody>
          {visible.slice(0, 50).map((player) => (
            <Row key={player.id} player={player} onSelect={(id) => setSelected(id)} />
          ))}
        </tbody>
      </table>
    </div>
  );
}

const counts = new Map();

export function countRender(label) {
  counts.set(label, (counts.get(label) ?? 0) + 1);
  window.__renderCounts__ = Object.fromEntries(counts);
}

export function resetCounts() {
  counts.clear();
}

import { createRoot } from 'react-dom/client';
import Dashboard from './Dashboard';

createRoot(document.getElementById('root')).render(<Dashboard />);

