import { useState, useMemo, useCallback, memo } from 'react';
import { countRender } from './renderCounter';

const ROWS = Array.from({ length: 2000 }, (_, i) => ({
  id: i,
  name: `Jugador ${i}`,
  score: (i * 37) % 500,
}));

const Row = memo(function Row({ player, onSelect }) {
  countRender('Row');
  return (
    <tr onClick={() => onSelect(player.id)}>
      <td>{player.name}</td>
      <td>{player.score}</td>
    </tr>
  );
});

const Toolbar = memo(function Toolbar({ onReset }) {
  countRender('Toolbar');
  return <button onClick={onReset}>Reiniciar</button>;
});

export default function Dashboard() {
  countRender('Dashboard');
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState(null);

  const visible = useMemo(
    () => ROWS.filter((row) => row.name.toLowerCase().includes(query.toLowerCase())),
    [query],
  );

  const handleSelect = useCallback((id) => setSelected(id), []);
  const handleReset = useCallback(() => setQuery(''), []);

  return (
    <div>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <Toolbar onReset={handleReset} />
      <p>Seleccionado: {selected ?? '—'}</p>
      <table>
        <tbody>
          {visible.slice(0, 50).map((player) => (
            <Row key={player.id} player={player} onSelect={handleSelect} />
          ))}
        </tbody>
      </table>
    </div>
  );
}

